def _norm(texto):
    t = unicodedata.normalize("NFKD", texto)
    t = "".join(c for c in t if not unicodedata.combining(c)).lower()
    t = " ".join(t.replace("–", "-").split())
    return t.replace(" - ", "-").replace(" -", "-").replace("- ", "-")


def _dados_iniciais() -> None:
    agora = datetime.now(UTC)
    t_dic = sa.table("dicionario", sa.column("id", sa.Uuid), sa.column("codigo"), sa.column("nome"),
                     sa.column("criado_em", sa.DateTime(timezone=True)), sa.column("versao"))
    t_termo = sa.table("termo", sa.column("id", sa.Uuid), sa.column("dicionario_id", sa.Uuid), sa.column("codigo"),
                       sa.column("nome"), sa.column("sigla"), sa.column("cor"), sa.column("classe"),
                       sa.column("ordem"), sa.column("ativo"), sa.column("criado_em", sa.DateTime(timezone=True)),
                       sa.column("versao"))
    t_sin = sa.table("termo_sinonimo", sa.column("id", sa.Uuid), sa.column("dicionario_id", sa.Uuid),
                     sa.column("termo_id", sa.Uuid), sa.column("texto"), sa.column("texto_normalizado"))
    for codigo, (nome, termos) in DICIONARIOS.items():
        did = uuid.uuid4()
        op.bulk_insert(t_dic, [{"id": did, "codigo": codigo, "nome": nome, "criado_em": agora, "versao": 1}])
        ids = {}
        linhas = []
        for i, (tc, tn, sigla, cor, classe) in enumerate(termos):
            ids[tc] = uuid.uuid4()
            linhas.append({"id": ids[tc], "dicionario_id": did, "codigo": tc, "nome": tn, "sigla": sigla, "cor": cor,
                           "classe": classe, "ordem": (i + 1) * 10, "ativo": True, "criado_em": agora, "versao": 1})
        op.bulk_insert(t_termo, linhas)
        sins = []
        for tc, textos in SINONIMOS.get(codigo, {}).items():
            for tx in textos:
                sins.append({"id": uuid.uuid4(), "dicionario_id": did, "termo_id": ids[tc], "texto": tx,
                             "texto_normalizado": _norm(tx)})
        if sins:
            op.bulk_insert(t_sin, sins)

    t_perm = sa.table("permissao", sa.column("id", sa.Uuid), sa.column("codigo"), sa.column("descricao"))
    op.bulk_insert(t_perm, [{"id": uuid.uuid4(), "codigo": c, "descricao": d} for c, (d, _) in PERMISSOES.items()])
    for codigo, (_d, papeis) in PERMISSOES.items():
        lista = ",".join(f"'{p}'" for p in papeis)
        op.execute(sa.text(
            "INSERT INTO papel_permissao (papel_id, permissao_id) "
            f"SELECT p.id, m.id FROM papel p, permissao m WHERE p.codigo IN ({lista}) AND m.codigo = '{codigo}'"))
